"""Independent brute-force reference implementation of PROTOCOL.md (slow, exact)."""
import itertools


def term_value(term, cells, names, nf):
    if 'const' in term:
        return term['const']
    if 'sum' in term:
        return sum(cells[ref[0] * nf + names[ref[1]]] for ref in term['sum'])
    if 'scale' in term:
        return term['scale'] * cells[term['ref'][0] * nf + names[term['ref'][1]]]
    return cells[term['ref'][0] * nf + names[term['ref'][1]]]


def cmp_value(left, op, right):
    return {'eq': left == right, 'ne': left != right, 'lt': left < right,
            'le': left <= right, 'gt': left > right, 'ge': left >= right}[op]


def pred_value(pred, cells, names, nf, slots):
    if pred['kind'] == 'cmp':
        left = term_value(pred['left'], cells, names, nf)
        right = term_value(pred['right'], cells, names, nf)
        return cmp_value(left, pred['op'], right)
    index = names[pred['field']]
    results = [cmp_value(cells[slot * nf + index], pred['op'], pred['value'])
               for slot in range(slots)]
    return any(results) if pred['kind'] == 'any' else all(results)


def job_tables(job):
    fields = job['fields']
    names = {f['name']: i for i, f in enumerate(fields)}
    nf = len(fields)
    slots = job['slots']
    domains = [f['domain'] for _ in range(slots) for f in fields]
    cells = nf * slots
    windows = [list(w) for w in job['train']]
    universe = []
    for positions in itertools.product(*[range(len(d)) for d in domains]):
        universe.append([domains[c][positions[c]] for c in range(cells)])
    def table(rows):
        return [[pred_value(p, row, names, nf, slots) for p in job['predicates']] for row in rows]
    return names, nf, slots, domains, cells, windows, universe, table(windows), table(universe)


def canonical(value):
    return str(value)


def solve(job):
    names, nf, slots, domains, cells, windows, universe, ttab, utab = job_tables(job)
    P = len(job['predicates'])
    width = job['width']
    rules = []
    for size in range(1, width + 1):
        for clause in itertools.combinations(range(P), size):
            # condition 1
            if not all(any(ttab[i][p] for p in clause) for i in range(len(windows))):
                continue
            # condition 2
            minimal = True
            witnesses = []
            for j, p in enumerate(clause):
                rest = tuple(q for q in clause if q != p)
                hit = [i for i in range(len(windows)) if not any(ttab[i][q] for q in rest)]
                if not hit:
                    minimal = False
                    break
                witnesses.append(min(i for i in hit if ttab[i][p]))
            if not minimal:
                continue
            # condition 3
            counter = None
            for u, row in enumerate(utab):
                if not any(row[p] for p in clause):
                    counter = u
                    break
            if counter is None:
                continue
            rules.append({'clause': list(clause), 'witnesses': witnesses, 'counterexample': counter})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))
    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]
    active_idx = [[tuple(c) for c in active]]
    answers = []
    for query in job['queries']:
        tcell = query['target'][0] * nf + names[query['target'][1]]
        fixed = [(b['ref'][0] * nf + names[b['ref'][1]], b['value']) for b in query['fixed']]
        prefix = query['prefix']
        completions = []
        for u, row in enumerate(universe):
            if not all(ttab_train_free(u, utab, active) for _ in [0]):
                continue
            if any(row[c] != v for c, v in fixed):
                continue
            if not canonical(row[tcell]).startswith(prefix):
                continue
            completions.append(u)
        if not completions:
            answers.append({'count': 0, 'tokens': [], 'witness': None})
            continue
        base = []
        for u, row in enumerate(universe):
            if not ttab_train_free(u, utab, active):
                continue
            if any(row[c] != v for c, v in fixed):
                continue
            base.append(u)
        tokens = []
        for digit in '0123456789':
            if any(canonical(universe[u][tcell]).startswith(prefix + digit) for u in base):
                tokens.append(digit)
        if prefix and (prefix == '0' or prefix[0] != '0'):
            if any(canonical(universe[u][tcell]) == prefix for u in base):
                tokens.append('END')
        answers.append({'count': len(completions), 'tokens': tokens, 'witness': completions[0]})
    return {'rules': rules, 'active': active, 'answers': answers}


def ttab_train_free(u, utab, active):
    row = utab[u]
    return all(any(row[p] for p in clause) for clause in active)
